import json
from pathlib import Path
P=Path(__file__).resolve().parent;paras=(P/'report.md').read_text().split('\n\n')
def evidence(start):return next(x for x in paras if x.startswith(start))
x={'ticker':'PSX','pros':[{'es':'La integración de refino y logística y el 98% de utilización en Q3 respaldan una ejecución fuerte, aunque no eliminan el riesgo de cracks, costes y paradas.','en':'Integrated refining and logistics, with 98% Q3 crude utilization, support strong execution but do not remove crack-spread, cost or outage risk.','evidence':evidence('PSX combina'),'sourceUrl':'https://www.sec.gov/Archives/edgar/data/1534701/000153470126000035/psx-2026930_ex991.htm'},{'es':'Coastal Bend y los proyectos de CPChem pueden ampliar capacidad en 2027. Son objetivos, no caja asegurada; no se valora Western Gateway como proyecto completo sin presupuesto detallado.','en':'Coastal Bend and CPChem projects could expand capacity in 2027. These are targets, not assured cash; Western Gateway is not valued as a full project without a detailed budget.','evidence':evidence('La dirección comunicó')}],'cons':[{'es':'CFO TTM de 15.028 millones incluye 1.783 de circulante; aun excluyéndolo, los cracks altos inflan la caja. El FCF reportado no equivale al flujo distribuible del común.','en':'TTM CFO of $15,028m includes $1,783m from working capital; even excluding it, high cracks boost cash. Reported FCF is not cash fully distributable to common shareholders.','evidence':evidence('CFO TTM'),'sourceUrl':'https://www.sec.gov/Archives/edgar/data/1534701/000153470126000037/psx-20260930.htm'},{'es':'DCF central $172,67 frente a cierre $271,94, con gran amplitud cíclica. El escenario adverso no es un suelo liquidativo ni el rango una probabilidad estadística.','en':'Base DCF $172.67 versus a $271.94 close, with wide cyclical scenarios. The downside case is not a liquidation floor and the range is not a statistical probability interval.','evidence':evidence('El DCF de dos componentes')}]}
(P/'pros_cons.json').write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
